// Parsear respuesta JSON del LLM - Estructura user
const items = $input.all();
const results = [];

for (const item of items) {
  let extracted = {};

  try {
    let content = item.json.message?.content || item.json.text || '';
    content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    extracted = JSON.parse(content);
  } catch (e) {
    extracted = {
      fecha: new Date().toLocaleDateString('es-AR'),
      nombre_empresa: 'No identificado',
      concepto: 'Pendiente revisión',
      tipo_comprobante: 'Otro',
      importe_sin_impuestos: null,
      iva: null,
      otros_impuestos: null,
      otros_impuestos_detalle: null,
      total: 0,
      id_transaccion: Date.now().toString(),
      categoria: 'otros',
      tipo_gasto: 'Único',
      parse_error: e.message
    };
  }

  // Asegurar que id_transaccion existe
  if (!extracted.id_transaccion || extracted.id_transaccion === '') {
    extracted.id_transaccion = Date.now().toString();
  }

  // Convertir montos a números si son strings
  const numFields = ['importe_sin_impuestos', 'iva', 'otros_impuestos', 'total'];
  for (const field of numFields) {
    if (extracted[field] !== null && extracted[field] !== undefined) {
      const val = String(extracted[field]).replace(/[^0-9.,\-]/g, '').replace(',', '.');
      extracted[field] = parseFloat(val) || null;
    }
  }

  // Normalizar categoría como safety net
  const categoriasValidas = ['combustible','alimentacion','transporte','servicios',
    'alquiler','impuestos','seguros','mantenimiento','salud','educacion',
    'entretenimiento','vestimenta','tecnologia','hogar','otros'];

  extracted.categoria = (extracted.categoria || 'otros')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  if (!categoriasValidas.includes(extracted.categoria)) {
    extracted.categoria = 'otros';
  }

  results.push({ json: extracted });
}

return results;

