const items = $input.all();
const gastos = items.map(i => i.json);

const normalize = (cat) => (cat || 'otros').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const mesesNombre = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',
  'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

let totalGeneral = 0;
const porCategoria = {};
const porMes = {};
const detalle = [];

for (const g of gastos) {
  const cat = normalize(g['Categoria'] || g.categoria || 'otros');
  const totalStr = String(g['Total $'] || g.total || '0').replace(/[^0-9.\-]/g, '');
  const total = parseFloat(totalStr) || 0;
  const fecha = g['Fecha'] || g.fecha || '';
  const empresa = g['Nombre Empresa'] || g.nombre_empresa || '-';
  const concepto = g['Concepto'] || g.concepto || '-';

  let mesKey = 'Sin fecha';
  let mesSort = 0;
  if (fecha) {
    const parts = fecha.split('/');
    if (parts.length === 3) {
      const mesIdx = parseInt(parts[1]) - 1;
      mesKey = mesesNombre[mesIdx] + ' ' + parts[2];
      mesSort = parseInt(parts[2]) * 100 + mesIdx;
    }
  }

  totalGeneral += total;

  if (!porCategoria[cat]) porCategoria[cat] = {total:0, count:0};
  porCategoria[cat].total += total;
  porCategoria[cat].count += 1;

  if (!porMes[mesKey]) porMes[mesKey] = {total:0, count:0, sort:mesSort};
  porMes[mesKey].total += total;
  porMes[mesKey].count += 1;

  detalle.push({fecha, empresa, concepto, categoria: cat, total});
}

const categoriasOrd = Object.entries(porCategoria)
  .sort((a,b) => b[1].total - a[1].total);
const mesesOrd = Object.entries(porMes)
  .sort((a,b) => a[1].sort - b[1].sort);

return [{json:{
  totalGeneral: totalGeneral.toFixed(2),
  cantTx: gastos.length,
  porCategoria: categoriasOrd.map(([cat,d]) => ({
    categoria:cat, total:d.total.toFixed(2), count:d.count,
    pct: totalGeneral > 0 ? ((d.total/totalGeneral)*100).toFixed(1) : '0'
  })),
  porMes: mesesOrd.map(([mes,d]) => ({mes, total:d.total.toFixed(2), count:d.count})),
  topCat: categoriasOrd[0] ? categoriasOrd[0][0] : 'N/A',
  topCatTotal: categoriasOrd[0] ? categoriasOrd[0][1].total.toFixed(2) : '0',
  promedio: gastos.length > 0 ? (totalGeneral/gastos.length).toFixed(2) : '0',
  detalle: detalle.sort((a,b) => b.total-a.total).slice(0,20)
    .map(d => ({...d, total:d.total.toFixed(2)})),
  fechaReporte: new Date().toLocaleDateString('es-AR',{year:'numeric',month:'long',day:'numeric'})
}}];

